=BRANCH_NAME="{{ $('Collect PR Data').first().json.branchName }}" && TICKET_KEY="{{ $('Collect PR Data').first().json.ticketKey }}" && TICKET_SUMMARY="{{ $('Collect PR Data').first().json.ticketSummary }}" && PR_URL="{{ $('Collect PR Data').first().json.prUrl }}" && PR_NUMBER="{{ $('Collect PR Data').first().json.prNumber }}" && PAGES_BASE="https://conanshin.github.io/n8n-ai-pipeline" && PROJECT_DIR="/home/node/workspace/project" && if [ ! -f "$PROJECT_DIR/preview.html" ]; then echo "Building preview.html from source components..." && COMP_TMP=$(mktemp) && for f in $(find "$PROJECT_DIR/src/components" -name "*.tsx" -o -name "*.jsx" 2>/dev/null | grep -v index | sort); do FNAME=$(basename "$f" .tsx) && echo "// --- $FNAME ---" >> "$COMP_TMP" && sed '/^import /d; s/^export default //g; s/^export //g' "$f" >> "$COMP_TMP" && echo "" >> "$COMP_TMP"; done && PAGE_COMP=$(find "$PROJECT_DIR/src/components/pages" -name "*.tsx" 2>/dev/null | grep -v index | head -1) && if [ -n "$PAGE_COMP" ]; then MAIN_COMP=$(basename "$PAGE_COMP" .tsx); else MAIN_COMP=$(find "$PROJECT_DIR/src/components" -name "*.tsx" | grep -v index | xargs wc -l 2>/dev/null | sort -rn | head -2 | tail -1 | awk '{print $NF}' | xargs basename | sed "s/.tsx//"); fi && echo "Main component: $MAIN_COMP" && { echo '<!DOCTYPE html>'; echo '<html lang="en">'; echo '<head>'; echo '<meta charset="UTF-8">'; echo '<meta name="viewport" content="width=device-width, initial-scale=1.0">'; echo "<title>$TICKET_KEY - $TICKET_SUMMARY</title>"; echo '<script src="https://cdn.tailwindcss.com"></script>'; echo '<script src="https://unpkg.com/react@18/umd/react.development.js" crossorigin></script>'; echo '<script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js" crossorigin></script>'; echo '<script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>'; echo '<style>body { margin: 0; }</style>'; echo '</head>'; echo '<body>'; echo '<div id="root"></div>'; echo "<script type=\"text/plain\" id=\"app-source\" data-main-component=\"$MAIN_COMP\">"; echo 'const { useState, useEffect, useCallback, useMemo, useRef } = React;'; echo ''; } > "$PROJECT_DIR/preview.html" && sed 's|</script>|<\\/script>|g' "$COMP_TMP" >> "$PROJECT_DIR/preview.html" && echo '</script>' >> "$PROJECT_DIR/preview.html" && cat >> "$PROJECT_DIR/preview.html" << 'FOOTEREOF'
<script>
(function() {
  var source = document.getElementById("app-source").textContent;
  var mainComp = document.getElementById("app-source").getAttribute("data-main-component");
  try {
    var compiled = Babel.transform(source, {
      presets: ["react", "typescript"],
      filename: "app.tsx"
    }).code;

    function parseInterfaceBody(body, fullSrc) {
      var props = {};
      var lines = body.split("\n");
      var i = 0;
      while (i < lines.length) {
        var line = lines[i].trim();
        i++;
        if (!line || line.startsWith("//") || line.startsWith("/*") || line.startsWith("*")) continue;
        var pm = line.match(/^(\/\*\*.*\*\/\s*)?(\w+)\??\s*:\s*(.+)/);
        if (!pm) continue;
        var propName = pm[2];
        var typeStr = pm[3].replace(/;\s*$/, "").trim();
        if (typeStr.includes("{")) {
          var braceCount = 0;
          for (var c = 0; c < typeStr.length; c++) {
            if (typeStr[c] === "{") braceCount++;
            if (typeStr[c] === "}") braceCount--;
          }
          while (braceCount > 0 && i < lines.length) {
            var nextLine = lines[i].trim();
            i++;
            typeStr += " " + nextLine;
            for (var c2 = 0; c2 < nextLine.length; c2++) {
              if (nextLine[c2] === "{") braceCount++;
              if (nextLine[c2] === "}") braceCount--;
            }
          }
          typeStr = typeStr.replace(/;\s*$/, "").trim();
        }
        props[propName] = genVal(typeStr, propName, fullSrc);
      }
      return props;
    }

    function generateSampleProps(src, compName) {
      var propsName = compName + "Props";
      var re = new RegExp("interface\\s+" + propsName + "\\s*\\{([\\s\\S]*?)\\n\\}", "m");
      var m = src.match(re);
      if (!m) return {};
      return parseInterfaceBody(m[1], src);
    }

    function genVal(t, name, src) {
      t = t.trim();
      if (t === "string") {
        if (/url|src|image|avatar|photo/i.test(name)) return "https://i.pravatar.cc/150?img=47";
        if (/email/i.test(name)) return "user@example.com";
        if (/name|username/i.test(name)) return "Jane Doe";
        if (/handle/i.test(name)) return "@janedoe";
        if (/title/i.test(name)) return "Sample Title";
        if (/desc/i.test(name)) return "Sample description text.";
        if (/action/i.test(name)) return "Performed an action";
        if (/timestamp|date|time/i.test(name)) return "2 hours ago";
        if (/label/i.test(name)) return "Label";
        if (/id/i.test(name)) return "id-" + Math.random().toString(36).substr(2, 6);
        return "Sample " + name;
      }
      if (t === "number") {
        if (/price|cost|amount|subtotal/i.test(name)) return 29.99;
        if (/count|total|quantity/i.test(name)) return 3;
        if (/followers|posts|likes/i.test(name)) return Math.floor(Math.random() * 500) + 100;
        return 42;
      }
      if (t === "boolean") return false;
      if (t === "number | string") return 42;
      if (t === "ReactNode" || t === "React.ReactNode") return null;
      if (t.endsWith("[]")) {
        var itemT = t.slice(0, -2).trim();
        var arr = [];
        for (var ai = 0; ai < 3; ai++) arr.push(genVal(itemT, name, src));
        return arr;
      }
      if (t.includes("=>")) return function(){};
      if (t.startsWith("{")) {
        var inner = t.slice(1);
        if (inner.endsWith("}")) inner = inner.slice(0, -1);
        // Convert top-level semicolons to newlines so parseInterfaceBody can split properly
        var normalized = "";
        var depth = 0;
        for (var si = 0; si < inner.length; si++) {
          if (inner[si] === "{") depth++;
          if (inner[si] === "}") depth--;
          if (inner[si] === ";" && depth === 0) {
            normalized += "\n";
          } else {
            normalized += inner[si];
          }
        }
        return parseInterfaceBody(normalized, src);
      }
      if (t.match(/^'[^']*'/)) {
        var um = t.match(/^'([^']*)'/);
        return um ? um[1] : t;
      }
      var cleanT = t.replace(/[<>\[\]]/g, "");
      var refRe = new RegExp("interface\\s+" + cleanT + "\\s*\\{([\\s\\S]*?)\\n\\}", "m");
      var rm = src.match(refRe);
      if (rm) {
        return parseInterfaceBody(rm[1], src);
      }
      return "sample";
    }

    var sampleProps = generateSampleProps(source, mainComp);
    console.log("Generated sample props:", JSON.stringify(sampleProps, null, 2));

    var fn = new Function("React", "ReactDOM", "sampleProps", "mainComp",
      compiled + "\n" +
      "try { var Comp = eval(mainComp); ReactDOM.createRoot(document.getElementById('root')).render(React.createElement(Comp, sampleProps)); } " +
      "catch(e) { console.error('Mount error:', e); document.getElementById('root').innerHTML = '<div style=\"padding:20px;color:red;\"><h2>Mount Error</h2><pre>' + e.message + '</pre></div>'; }"
    );
    fn(React, ReactDOM, sampleProps, mainComp);
  } catch(e) {
    console.error("Babel compilation error:", e);
    document.getElementById("root").innerHTML = '<div style="padding:20px;color:red;"><h2>Compilation Error</h2><pre>' + e.message + '</pre></div>';
  }
})();
</script>
</body>
</html>

FOOTEREOF
