// Extract error information from the Error Trigger output
const errorData = $input.first().json;
const execution = errorData.execution || {};
const lastNode = execution.lastNodeExecuted || 'Unknown';
const errorMsg = execution.error?.message || errorData.error?.message || 'Unknown error';
const workflowName = errorData.workflow?.name || 'Jira-to-Code AI Pipeline';
const executionId = execution.id || 'N/A';

// Try to get ticket info from execution data
let ticketKey = 'N/A';
let ticketSummary = 'N/A';
try {
  const resultData = execution.data?.resultData?.runData;
  if (resultData && resultData['Combine Data']) {
    const combineOutput = resultData['Combine Data'][0]?.data?.main?.[0]?.[0]?.json;
    if (combineOutput) {
      ticketKey = combineOutput.ticketKey || 'N/A';
      ticketSummary = combineOutput.ticketSummary || 'N/A';
    }
  }
} catch(e) {}

return {
  lastNode,
  errorMsg,
  workflowName,
  executionId,
  ticketKey,
  ticketSummary
};

